    near: [Math.round(9 + a * g.swing * w), Math.round(22 + hipY + g.reach - Math.max(0, a) * 2.5 * w)],
    far: [Math.round(15 - a * g.swing * 1.2 * w), Math.round(22 + hipY + g.reach - Math.max(0, -a) * 2.5 * w)],
